  const h = vfsState.handlers;
  if (h !== null) {
    const result = h.fstatSync(fd);
    if (result !== undefined) return result;
  }
  const stats = binding.fstat(fd, options.bigint, undefined, false);
  if (stats === undefined) {
    return;
  }
  return getStatsFromBinding(stats);
}

/**
