  if (h !== null) {
    const result = h.fchmodSync(fd);
    if (result !== undefined) return;
  }

  if (permission.isEnabled()) {
    throw new ERR_ACCESS_DENIED('fchmod API is disabled when Permission Model is enabled.');
  }
  binding.fchmod(
    fd,
    parseFileMode(mode, 'mode'),
  );
