}

const kKeyTypesBufferOnly = [
  'ArrayBuffer',
  'Buffer',
  'TypedArray',
  'DataView',
];

function getKeyTypes({ allowKeyObject, allowURL = false }) {
  return [
    ...kKeyTypesBufferOnly,
    'string',
    ...(allowKeyObject ? ['KeyObject', 'CryptoKey'] : []),
    ...(allowURL ? ['URL'] : []),
