    // An unborn default is a real state -- a repository with no commits yet --
    // and reporting it as null says so rather than failing the read.
    try { at = git(dir, ['rev-parse', branch]) } catch { /* nothing on it yet */ }
    out.push({ repo: name, branch, at })
  }
  return out
}

const isProtected = branch => protectedBranches().some(p => p.branch === branch)

// Said the same way wherever it is refused, so the reason does not get a
// different wording depending on which door it was met at.
function whyProtected (branch) {
  const p = protectedBranches().find(x => x.branch === branch)
  if (!p) return null
  return `"${branch}" is the default branch of ${p.repos.join(', ')}. Work goes onto its own branch and is merged here afterwards, so nothing is built directly on it.`
}

// ---- getting out of the way --------------------------------------------

// Some operations need a working tree, so they cannot go through --git-dir.
const gitIn = (repoPath, args) => execFileSync('git', ['-C', repoPath, ...args], {
  encoding: 'utf8',
  timeout: 30000,
  windowsHide: true
}).trim()

const pathOf = repo => path.join(serve.DIR, repo)

// Whether a repository has anything uncommitted -- tracked or not.
function isClean (repo) {
  try { return gitIn(pathOf(repo), ['status', '--porcelain']) === '' } catch { return false }
}

// If a repository is sitting on `branch`, step it back onto its default so the
// branch can be used.
//
// Only when the working tree is CLEAN. A checkout that has been read is worth
// nothing and is free to move; one that has been edited is somebody's work, and
// moving off it to unblock a machine would be this app deciding whose work
// matters more. So that case is reported instead, naming what is in the way.
//
// Bare repositories are skipped: they have no working tree, nothing is checked
// out in the sense that matters, and git accepts the push regardless.
function freeIfBusy (repo, branch) {
  const dir = serve.gitDirOf(repo)
  if (!dir || dir === pathOf(repo)) return { repo, freed: false, busy: false }
  if (headOf(dir) !== branch) return { repo, freed: false, busy: false }

  const home = defaultOf(repo)
  if (!home || home === branch) return { repo, freed: false, busy: false }

  if (!isClean(repo)) {
    return {
      repo,
      freed: false,
      busy: true,
      why: `${repo} has "${branch}" checked out here with uncommitted changes, so it cannot be moved off it. Commit or discard them, or switch ${repo} back to ${home}.`
    }
  }

  gitIn(pathOf(repo), ['checkout', '--quiet', home])
  return { repo, freed: true, busy: false, from: branch, to: home }
}

// The same, for every repository at once. Used before a machine is set up on a
// branch and before it pushes one, because both are moments where a checkout
// left open on the host would otherwise fail something that has nothing to do
// with it.
function freeEverywhere (branch) {
  return serve.list().map(r => freeIfBusy(r.name, branch)).filter(r => r.freed || r.busy)
}

// Repositories sitting away from their default branch, and whether that can be
// undone on its own.
//
// Asked on every draw, so it is written to cost nothing in the ordinary case:
// reading HEAD is a ref lookup, and only a repository that is actually somewhere
// else gets a status. Almost always that is none of them.
//
// A DIRTY one is worth putting in front of the operator rather than leaving for
// whoever meets it next. It will refuse a push from the machine that needs that
// branch, and the machine's own error cannot say why -- it does not know this
// working tree exists. Reported here, it is a sentence about a file somebody
// left open; met there, it is a message about a configuration variable.
function blocking () {
  const out = []
  for (const { name } of serve.list()) {
    const dir = serve.gitDirOf(name)
    if (!dir || dir === pathOf(name)) continue
    const head = headOf(dir)
    const home = defaultOf(name)
    if (!head || !home || head === home) continue
    out.push({ repo: name, on: head, home, clean: isClean(name) })
  }
  return out
}

// Every branch across the workspace, and which repositories have each.
//
// The union rather than the intersection, and each one says which repositories
// it is missing from. A name present in three of four repositories is the normal
// state of a change that only touched three -- reporting it as absent would hide
// the work, and reporting it as present everywhere would claim repositories that
// have nothing on it.
function all () {
  const repos = serve.list()
  const seen = new Map()

  for (const { name } of repos) {
    const dir = serve.gitDirOf(name)
    if (!dir) continue
    const head = headOf(dir)
    for (const branch of branchesIn(dir)) {
      if (!seen.has(branch)) seen.set(branch, { name: branch, in: [], head: [] })
      seen.get(branch).in.push(name)
      if (branch === head) seen.get(branch).head.push(name)
    }
  }

  const names = repos.map(r => r.name)
  const guarded = protectedBranches()

  return {
    repos: names,
    protected: guarded,
    branches: [...seen.values()]
      .map(b => {
        const p = guarded.find(g => g.branch === b.name)
        // Checked out somewhere with uncommitted work in it. NOT the same as
        // being checked out: a clean checkout is stepped out of when the branch
        // is needed, so it stays available and nobody has to think about it.
        // Only work in the way makes a branch unusable, and then it is the work
        // that is named rather than the branch.
        const stuck = p ? [] : serve.list()
          .map(r => freeIfBusy(r.name, b.name))
          .filter(r => r.busy)

        // TWO questions, kept apart, because they have different answers and
        // different ways out.
        //
        //   protected   -- may this branch be worked on at all? No amount of
        //                  tidying changes it. Pick another one.
        //   reclaimable -- can the host get out of the way? It usually can, by
        //                  stepping off a clean review checkout. When it cannot,
        //                  the fix is to that working tree, not to this choice.
        //
        // Collapsing them into one "available" was tempting and wrong: it would
        // answer "no" to both with the same sentence, and send somebody looking
        // for another branch when what they actually had was two minutes of
        // uncommitted work in a checkout they had forgotten about.
        return {
          ...b,
          missing: names.filter(n => !b.in.includes(n)),
          protected: !!p,
          reclaimable: !stuck.length,
          blocked: stuck.length ? stuck.map(s => s.why) : null,
          why: p ? whyProtected(b.name) : (stuck.length ? stuck[0].why : null)
        }
      })
      .sort((a, b) => a.name.localeCompare(b.name))
  }
}

// A branch name git will actually accept, checked before anything is created.
//
// Asked of git rather than matched against a pattern here: git's rules are more
// particular than they look (no `..`, no trailing `.lock`, no `@{`, no leading
// or trailing slash) and a second implementation of them would be wrong in a way
// that only shows up on an unusual name.
function nameIsOk (branch) {
  if (!branch || !branch.trim()) return 'A branch needs a name.'
  try {
    execFileSync('git', ['check-ref-format', '--branch', branch.trim()], { timeout: 10000, windowsHide: true, stdio: 'ignore' })
    return null
  } catch {
    return `Git will not accept "${branch}" as a branch name.`
  }
}

// Cut the branch in every repository that does not have it yet, from wherever
// that repository currently is.
//
// It does not touch the default branch, and cannot: creating a ref neither moves
// another one nor disturbs a working tree. A repository that already has the
// branch is left exactly as it is -- that is what picking an existing name means,
// and rewinding it to today's HEAD would silently discard the work that made the
// name worth reusing.
function ensure (branch) {
  const why = nameIsOk(branch)
  if (why) throw new Error(why)
  const name = branch.trim()

  // Refused here as well as at the dialog and at the push, because this is the
  // function that would otherwise CREATE the situation -- recording a machine
  // against the default branch. A rule that only exists where it is offered is
  // not a rule.
  const guarded = whyProtected(name)
  if (guarded) throw new Error(guarded)

  return serve.list().map(({ name: repo }) => {
    const dir = serve.gitDirOf(repo)
    const had = branchesIn(dir).includes(name)
    if (!had) git(dir, ['branch', name])
    return { repo, branch: name, created: !had, from: had ? null : headOf(dir) }
  })
}

module.exports = {
  all, ensure, nameIsOk, branchesIn, headOf, defaultHeads,
  defaultOf, protectedBranches, isProtected, whyProtected,
  isClean, freeIfBusy, freeEverywhere, blocking
}

'use strict'

// A minimal mocha-shaped harness: describe, it, run.
//
// Ported from test-moniker by the operator of this project:
//   https://github.com/bm-ok/test-moniker  --  harness.js
//
// Kept deliberately close to the original. The shape is the value -- registration
// separated from execution, a context injected into every test rather than
// imported by it, and progress reported through callbacks instead of printed --
// and drifting from it would make the two versions diverge for no reason. What
// changed is noted where it changed, and nothing else.
//
// WHY THIS IS HERE AT ALL. The drills in TEST-PLAN.md were prose: a person read
// them and typed the commands. Prose cannot report a status, cannot be listed in
// a window, and quietly rots against the code it describes. Declared with
// describe/it they become things this app can enumerate, offer as a pre-defined
// task, run, and report on one test at a time.
//
// The injected context is what makes that work here. A test is handed the
// actions table, so a drill drives this tool exactly the way a person does --
// through the same surface, with the same refusals -- rather than reaching past
// it into the modules underneath and proving something about code nobody uses.

const suites = []
let currentSuite = null

function describe (name, fn) {
  const suite = { name, tests: [] }
  suites.push(suite)
  currentSuite = suite
  try {
    fn()
  } finally {
    currentSuite = null
  }
}

function it (name, fn) {
  if (!currentSuite) throw new Error('it() must be called inside describe()')
  currentSuite.tests.push({ name, fn })
}

// The assertions, deliberately three. A rich assertion library is a language to
// learn before a drill can be read; these three say the whole of what a drill
// needs and the message carries the rest.
function ok (cond, msg) {
  if (!cond) throw new Error(msg || 'Assertion failed')
}

function equal (a, b, msg) {
  if (a !== b) throw new Error(msg || `Expected ${a} === ${b}`)
}

function notEqual (a, b, msg) {
  if (a === b) throw new Error(msg || `Expected ${a} !== ${b}`)
}

// ADDED HERE, and the only real addition to the original.
//
// Half of what this project needs to prove passes by being REFUSED: a machine
// holding a credential cannot be snapshotted, a guest cannot push to the default
// branch, a signed-out worker cannot be given work. Written with ok() that reads
// as a try/catch in every drill, and the thing being asserted -- that it threw,
// and threw about the right subject -- gets buried in the plumbing.
//
// A refusal that happens for the wrong reason is not a pass, so the message is
// matched rather than merely the throwing.
async function refuses (fn, expected, msg) {
  let threw = null
  try {
    await fn()
  } catch (e) {
    threw = e
  }
  if (!threw) throw new Error(msg || 'Expected this to be refused, and it was allowed')
  if (expected && !new RegExp(expected, 'i').test(threw.message || '')) {
    throw new Error(`${msg || 'Refused, but for the wrong reason'} — expected something matching /${expected}/, got: ${threw.message}`)
  }
  return threw
}

const assert = { ok, equal, notEqual, refuses }

async function run (context = {}) {
  const results = { suites: [], passed: 0, failed: 0 }
  const {
    timeoutMs = 0,
    testFilter,
    onTestStart,
    onTestEnd
  } = context

  const log = (context.log && typeof context.log === 'function')
    ? context.log
    : ((...args) => { try { console.log('[harness]', ...args) } catch { /* nowhere to say it */ } })

  for (const suite of suites) {
    const suiteRes = { name: suite.name, tests: [] }
    let announced = false

    for (const t of suite.tests) {
      if (typeof testFilter === 'function' && !testFilter(t.name, suite.name)) continue

      // Moved inside the loop, after the filter. The original announces every
      // suite before filtering, which for a run of one drill prints the name of
      // every suite that is about to be skipped -- and here that output goes to
      // the operator's live log rather than a terminal nobody is reading.
      if (!announced) { log(`suite: ${suite.name}`); announced = true }

      const testRes = { name: t.name, ok: false, error: null }
      const started = Date.now()

      try { if (onTestStart) onTestStart({ suiteName: suite.name, testName: t.name }) } catch { /* a reporter must not fail a test */ }
      try { if (context.onTestUpdate) context.onTestUpdate({ suiteName: suite.name, testName: t.name, status: 'running' }) } catch { /* as above */ }

      try {
        const testPromise = (async () => {
          await t.fn({ ...context, assert })
        })()

        if (timeoutMs > 0) {
          const timeoutPromise = new Promise((_, rej) => {
            const id = setTimeout(() => {
              rej(new Error(`Test timeout after ${timeoutMs}ms`))
            }, timeoutMs)
            testPromise.then(() => clearTimeout(id), () => clearTimeout(id))
          })
          await Promise.race([testPromise, timeoutPromise])
        } else {
          await testPromise
        }

        try { if (context.onTestUpdate) context.onTestUpdate({ suiteName: suite.name, testName: t.name, status: 'passed' }) } catch { /* as above */ }
        testRes.ok = true
        testRes.ms = Date.now() - started
        results.passed++
        log(`  PASS ${t.name} (${Math.round(testRes.ms / 1000)}s)`)
      } catch (e) {
        testRes.ok = false
        testRes.ms = Date.now() - started
        testRes.error = e && (e.stack || e.message || String(e))
        try { if (context.onTestUpdate) context.onTestUpdate({ suiteName: suite.name, testName: t.name, status: 'failed', error: testRes.error }) } catch { /* as above */ }
        results.failed++
        log(`  FAIL ${t.name} -> ${e && (e.message || e)}`)
      }

      try { if (onTestEnd) onTestEnd({ suiteName: suite.name, testName: t.name, result: testRes }) } catch { /* as above */ }

      suiteRes.tests.push(testRes)
    }

    // Only suites that actually ran something. A run of one drill should report
    // one suite, not every suite with an empty list beside it.
    if (suiteRes.tests.length) results.suites.push(suiteRes)
  }

  return results
}

// What a definition IS, as a number.
//
// Definitions here are written by a model at the operator's request and then
// approved by the operator. An approval that survived the definition being
// edited afterwards would be worth nothing -- write something modest, get it
// approved, change what it does. So an approval is recorded against this, and
// lapses the moment the source moves.
//
// The source of the function, because that is the whole of what will run. Not
// the name, which is what a person recognises and exactly what an edit would
// keep.
function fingerprint (fn) {
  const src = String(fn)
  let h = 5381
  for (let i = 0; i < src.length; i++) h = ((h * 33) ^ src.charCodeAt(i)) >>> 0
  return `${h.toString(16)}-${src.length}`
}

// What is registered, without running any of it. This is what the window lists
// in the "Pre-defined" half of the write-a-task dialog, and it must not have
// side effects: opening a dialog is not consent to run a drill.
//
// The source travels with it, because approving something you have not read is
// not approval. The dialog shows it.
function getRegisteredSuites () {
  return suites.map(s => ({
    name: s.name,
    tests: s.tests.map(t => ({
      name: t.name,
      fingerprint: fingerprint(t.fn),
      source: String(t.fn)
    }))
  }))
}

module.exports = { describe, it, run, assert, getRegisteredSuites, fingerprint }

'use strict'

// Which pre-defined tasks a person has actually approved.
//
// THE LOOP THIS EXISTS FOR. The operator asks the supervising model to write a
// definition; the model writes it; the operator reads it and approves it; only
// then can it be picked and run. The model does the writing, which is the point
// of having one -- and it cannot ratify its own work, which is the point of
// this file.
//
// That is the same rule the supervisor already works under, applied one level
// up. A supervisor sends a bad document back rather than fixing it, because the
// supervisor's own edits are the one path nothing reviews. A definition it wrote
// and approved itself would be exactly that path, reopened.
//
// AN APPROVAL IS OF A DEFINITION, NOT OF A NAME. It is recorded against a
// fingerprint of the function that will run, and lapses the moment that source
// moves. Otherwise the way around it is obvious and quiet: get something modest
// approved, then change what it does. A lapsed approval is reported as lapsed
// rather than as missing, because those are different situations -- one has
// never been read, the other has been read and then edited.

const fs = require('node:fs')
const path = require('node:path')
const log = require('../core/log')

const STATE = process.env.OKC_STATE || path.join(__dirname, '..', 'state')
const FILE = path.join(STATE, 'approvals.json')

// Suite and name together. A test name is only unique inside its suite, and two
// suites with a test called "it is refused" is not a strange thing to expect.
const keyOf = (suite, name) => `${suite}::${name}`

function read () {
  try { return JSON.parse(fs.readFileSync(FILE, 'utf8').replace(/^﻿/, '')) || {} } catch { return {} }
}

function write (all) {
  fs.mkdirSync(STATE, { recursive: true })
  fs.writeFileSync(FILE, JSON.stringify(all, null, 2))
}

// What an approval says about one test, right now.
//
// Three answers rather than two, because "never approved" and "approved, then
// edited" want different things from the reader: one is work waiting to be read,
// the other is a change waiting to be read. Collapsing them into `false` hides
// which.
function stateOf (suite, name, fingerprint) {
  const all = read()
  const rec = all[keyOf(suite, name)]
  // What the model said when it changed this, if it said anything. Carried into
  // every answer, because "changed" on its own tells a reader that something is
  // different and nothing about what or why -- which leaves them diffing source
  // in their head to find out whether they care.
  const asked = rec && rec.request && rec.request.fingerprint === fingerprint ? rec.request : null

  if (!rec) return { approved: false, lapsed: false, why: 'has never been approved', request: asked }
  if (rec.fingerprint !== fingerprint) {
    return {
      approved: false,
      lapsed: true,
      at: rec.at,
      request: asked,
      why: asked
        ? `was approved on ${new Date(rec.at).toLocaleDateString()} and has been changed since. The reason given: ${asked.why}`
        : `was approved on ${new Date(rec.at).toLocaleDateString()} and has been changed since, with no reason given. Read it again.`
    }
  }
  return { approved: true, lapsed: false, at: rec.at, note: rec.note || null, why: null, request: null }
}

// A model asking to have a change looked at.
//
// THIS IS THE HALF A MODEL IS ALLOWED. It may edit a definition and it may ask
// for the edit to be read; it may not decide that the edit is alright. Recorded
// against the NEW fingerprint, so a reason cannot outlive the change it explains
// -- edit again and the reason goes stale with it.
//
// Kept beside the old approval rather than replacing it, because the reader
// wants both: what they approved before, and what is being asked now.
function request (suite, name, fingerprint, why) {
  if (!String(why || '').trim()) throw new Error('Say why it changed. A request to re-read something, with no reason, is just the change arriving quietly.')
  const all = read()
  const key = keyOf(suite, name)
  all[key] = {
    ...(all[key] || { suite, name }),
    request: { fingerprint, why: String(why).trim(), at: new Date().toISOString() }
  }
  write(all)
  log.on('drill').warn(`re-reading asked for: ${name} — ${String(why).trim()}`)
  return all[key].request
}

function approve (suite, name, fingerprint, note) {
  const all = read()
  // The request is cleared, not kept. It was a question, and this is the answer;
  // leaving it would make the next reader think something is still outstanding.
  all[keyOf(suite, name)] = {
    suite,
    name,
    fingerprint,
    note: note || null,
    at: new Date().toISOString()
  }
  write(all)
  log.on('drill').good(`approved: ${name}`)
  return all[keyOf(suite, name)]
}

function withdraw (suite, name) {
  const all = read()
  const key = keyOf(suite, name)
  if (!all[key]) return { withdrawn: false, why: 'it was not approved' }
  delete all[key]
  write(all)
  log.on('drill').warn(`approval withdrawn: ${name}`)
  return { withdrawn: true }
}

module.exports = { read, stateOf, approve, request, withdraw, keyOf, FILE }

'use strict'

// What a run left behind, kept HERE, where the machine cannot take it away.
//
// THE PROBLEM THIS FIXES, which was found the hard way and more than once. A
// run's output and the worker's transcript live in `~/.okc-runs` on the machine
// that did the work -- and a machine is the disposable half of this tool. It
// gets rolled back to a snapshot, or deleted, or rebuilt, and every one of those
// is a normal and correct thing to do. Doing it takes the only account of what
// happened with it.
//
// That was not hypothetical: two rollbacks in one afternoon erased the record of
// two runs whose results had already been reported. What remained was a task
// record saying work was done and nothing at all saying how.
//
// So a finished run is pulled across and kept beside the task, in the data
// directory rather than the repository -- it is produced by running, not by
// writing, and the same reasoning that puts screenshots there puts this there.
// The machine's copy stays where it is; this is a copy, not a move, because
// moving would mean the machine's own record depended on this host being
// reachable at the moment it finished.
//
// REDACTED ON THE WAY IN. This is the boundary the credential rules already name:
// output crossing from a machine is KEPT here, permanently, so a token that
// reached a worker's output is not a moment of exposure but a filing. Cleaned
// here is the only place it can be stopped.

const fs = require('node:fs')
const path = require('node:path')
const data = require('../core/data')
const secret = require('../core/secret')

const ROOT = () => data.sub('task-logs')

// One folder per task, one per run inside it. A flat directory of run ids would
// be sortable and useless: the question is always "what happened to this task",
// and the answer should not require knowing which run ids belonged to it.
const dirFor = (task, run) => path.join(ROOT(), safe(task), safe(run))

// Task and run ids are made here and are already tame, but they arrive through
// an action and an action's arguments are somebody else's text.
const safe = s => String(s || 'unknown').replace(/[^A-Za-z0-9._-]/g, '_').slice(0, 120)

const has = (task, run) => {
  try { return fs.existsSync(path.join(dirFor(task, run), 'out.log')) } catch { return false }
}

// Kept once and never rewritten.
//
// A finished run does not change, and re-pulling it would mean the kept copy
// silently follows whatever the machine says today -- including saying nothing,
// after a rollback. The first copy taken is the record.
function keep (task, run, { output, session, machine, state, exit } = {}) {
  const dir = dirFor(task, run)
  if (has(task, run)) return { kept: false, why: 'already kept', dir }

  fs.mkdirSync(dir, { recursive: true })
  fs.writeFileSync(path.join(dir, 'out.log'), secret.redact(output || ''))
  if (session) fs.writeFileSync(path.join(dir, 'session.json'), secret.redact(JSON.stringify(session, null, 2)))
  fs.writeFileSync(path.join(dir, 'about.json'), JSON.stringify({
    task, run, machine: machine || null, state: state || null, exit: exit === undefined ? null : exit,
    kept: new Date().toISOString()
  }, null, 2))
  return { kept: true, dir }
}

// Everything kept for one task, oldest first. Read from the directory rather
// than from the task record, so a run whose task was thrown away is still
// findable -- the log outlives the note about it, which is the right way round.
function list (task) {
  const dir = path.join(ROOT(), safe(task))
  let runs = []
  try { runs = fs.readdirSync(dir, { withFileTypes: true }).filter(e => e.isDirectory()).map(e => e.name) } catch { return [] }
  return runs.sort().map(run => {
    let about = {}
    try { about = JSON.parse(fs.readFileSync(path.join(dir, run, 'about.json'), 'utf8')) } catch { /* an interrupted keep */ }
    let bytes = 0
    try { bytes = fs.statSync(path.join(dir, run, 'out.log')).size } catch { /* as above */ }
    return { run, ...about, bytes, dir: path.join(dir, run) }
  })
}

function read (task, run, { lines = 200 } = {}) {
  const file = path.join(dirFor(task, run), 'out.log')
  let text = ''
  try { text = fs.readFileSync(file, 'utf8') } catch {
    return { found: false, why: 'nothing was kept for that run here', file }
  }
  const all = text.split('\n')
  const want = Math.max(1, Number(lines) || 200)
  return {
    found: true,
    file,
    lines: all.length,
    // The tail, because output ends with what happened. The whole file is on
    // disk and its path is returned, so nothing is hidden -- only not carried.
    text: all.slice(-want).join('\n'),
    more: Math.max(0, all.length - want)
  }
}

module.exports = { keep, list, read, has, dirFor, ROOT }

'use strict'

// Work waits for a machine; a machine does not wait for work.
//
// THE NATURAL STATE OF A RUNNER IS OFF. That is the whole shape of this file.
// A machine is not a thing you keep warm and hand jobs to -- it is switched on
// because there is something to do, brought to a known state, given exactly one
// task, and switched off again when that task is done. Between tasks there is
// nothing running, nothing holding a credential, and nothing to go stale.
//
// So a task does not name a machine. It waits, and the first machine that is
// free takes it. Which machine did the work is a fact recorded afterwards rather
// than a decision made in advance, and that is what makes a second runner useful
// without anybody rebalancing anything.
//
// CLEAN FIRST, AND THAT MEANS ROLLED BACK. A machine that has done a task is
// carrying that task: its branch, its checkout, its files, whatever the worker
// left in a home directory. Reusing it would let one task's leavings reach
// another's work, which is not a hypothetical -- the whole reason a task is
// judged by its branch is that anything else is somebody's account of what
// happened. So the machine is restored to its base snapshot before it is
// started, every time, and a machine with no base snapshot is not available:
// there is nowhere clean to bring it back to.
//
// EVERY STEP GOES THROUGH THE ACTIONS. This drives the same surface a person
// drives, so every refusal still applies -- the protected default, the branch
// claim, a machine that may not be moved off its branch. A scheduler with its
// own private path to the machines would be a second set of rules, and the
// second set is always the one that turns out to be wrong.

const TICK = 15000

// One task at a time per machine, and one machine at a time per task. Held in
// memory rather than in the task file because it describes what THIS process is
// doing right now: a dashboard that has just restarted is not running anything,
// whatever the file says, and a stale claim in a file would keep a machine out
// of service until somebody noticed.
const busyWith = new Map()

let running = false
let timer = null

function begin (actions, log) {
  if (timer) return
  // Adopted before anything new is started, so a restart mid-task does not hand
  // that machine a second one.
  adopt(actions, log).catch(() => { /* said inside */ })
  timer = setInterval(() => tick(actions, log).catch(e => log.on('queue').warn(e.message)), TICK)
  if (timer.unref) timer.unref()
}

const stop = () => { if (timer) { clearInterval(timer); timer = null } }

// ---- who is free -------------------------------------------------------

// A machine that can be given something, and the reasons one cannot.
//
// Reported with a reason rather than filtered silently, because "nothing is
// running and nothing is queued either" and "everything is queued and no machine
// can take it" look identical from outside and want opposite responses.
function availability (vms) {
  return vms.map(v => {
    // A decision, checked before any of the facts. Someone has said keep this
    // one back, and that outranks it merely looking idle -- which is exactly
    // what a machine somebody is about to use looks like.
    if (v.forTasks === false) return { name: v.name, free: false, why: 'is kept back from the queue' }
    if (busyWith.has(v.name)) return { name: v.name, free: false, why: `doing ${busyWith.get(v.name)}` }
    if (!v.baseSnapshot) return { name: v.name, free: false, why: 'has no base snapshot to come back to, so it cannot be made clean' }
    if (v.branch) return { name: v.name, free: false, why: `still claims ${v.branch}` }
    if (v.stage && v.stage === 'installing') return { name: v.name, free: false, why: 'is being installed' }
    return { name: v.name, free: true, why: null }
  })
}

// ---- the loop ----------------------------------------------------------

async function tick (actions, log) {
  if (running) return
  running = true
  try {
    const { tasks } = await actions.tasks.run({})
    // Oldest first. A queue that is not first-in-first-out is a queue somebody
    // has to reason about, and the number is the order they were written.
    const waiting = tasks.filter(t => t.state === 'queued').sort((a, b) => a.number - b.number)
    if (!waiting.length) return

    const { vms } = await actions.vmList.run({})
    const free = availability(vms).filter(a => a.free)
    if (!free.length) return

    for (const task of waiting) {
      const next = free.shift()
      if (!next) break
      // Claimed synchronously, before any await, so two ticks cannot hand the
      // same machine to two tasks.
      busyWith.set(next.name, `#${task.number}`)
      run(actions, log, task, next.name).catch(async e => {
        log.on('queue', next.name).bad(`#${task.number} — ${e.message}`)
        // A task whose setup failed has to LAND somewhere.
        //
        // It threw before it could be marked done, so it stayed in `given` for
        // ever: not queued, so nothing would pick it up; not done, so the board
        // showed it working with no worker anywhere; and on the next restart the
        // queue would adopt it and put its machine away all over again.
        //
        // Marked done rather than re-queued, deliberately. The attempt happened
        // and produced nothing, which is a true and useful thing to see -- and a
        // task that re-queues itself onto a machine that just failed to boot
        // does that for ever, quietly, with nobody deciding anything.
        try {
          await actions.taskUpdate.run({
            id: task.id,
            task: {
              state: 'done',
              attempts: [...(task.attempts || []), { machine: next.name, at: new Date().toISOString(), failed: e.message }]
            }
          })
        } catch { /* the log already carries it */ }
      })
    }
  } finally {
    running = false
  }
}

// ---- one task, start to finish ----------------------------------------

async function run (actions, log, task, machine) {
  const to = log.on('queue', machine)
  const id = task.id

  // How long each part took, kept with the attempt.
  //
  // A total is nearly useless for finding a fault: "the task took nine minutes"
  // says nothing about whether the machine took eight of them to boot. These are
  // the numbers that make a slow step visible afterwards, when nobody was
  // watching the log at the time -- which is most of the time, since the point of
  // a queue is being able to walk away from it.
  const spent = {}
  const began = Date.now()
  const phase = async (name, fn) => {
    const at = Date.now()
    try { return await fn() } finally { spent[name] = Date.now() - at }
  }

  try {
    to.info(`#${task.number} "${task.title}" -> ${machine}`)
    await actions.taskUpdate.run({ id, task: { state: 'given', machine } })

    // --- clean, then on ---------------------------------------------------
    //
    // Rolled back before it is started rather than after it is finished. Both
    // would work and only this one is honest: a machine cleaned "afterwards" is
    // clean only if the last thing that touched it finished properly, and the
    // interesting failures are exactly the ones that did not.
    await phase('bringUp', () => bringUp(actions, to, machine))

    // --- give it the work -------------------------------------------------
    await phase('credential', () => actions.vmCredentialsPut.run({ name: machine }))
    await phase('workspace', () => actions.vmWorkspace.run({ name: machine, branch: task.branch, folder: task.folder || undefined }))
    const started = await actions.vmDispatch.run({
      name: machine,
      task: task.brief,
      folder: task.folder || undefined,
      contract: task.contract || undefined
    })
    const fresh = await actions.tasks.run({})
    const now = fresh.tasks.find(t => t.id === id) || task
    await actions.taskUpdate.run({
      id,
      task: {
        run: started.run,
        attempts: [...(now.attempts || []), { run: started.run, machine, at: new Date().toISOString() }]
      }
    })

    // --- wait for it ------------------------------------------------------
    const outcome = await phase('work', () => waitForRun(actions, to, machine, started.run))

    // Pulled across before the machine is touched again. taskProgress does this
    // too, but that only happens if somebody looks -- and this machine is about
    // to be shut down and rolled back, which is precisely when nobody is.
    await actions.taskProgress.run({ id }).catch(() => { /* the log is best effort; the verdict is not */ })

    const art = await actions.taskArtifact.run({ id })

    // Marked done whatever the outcome was, because done is about the run
    // having ended and not about it having worked. Whether anything actually
    // arrived is read from the branch, and stays a separate question -- a task
    // can be done and have delivered nothing, which is exactly what a worker
    // that was refused by the hook looks like.
    spent.total = Date.now() - began
    const latest = (await actions.tasks.run({})).tasks.find(t => t.id === id)
    const marked = (latest.attempts || []).map(a => a.run === started.run ? { ...a, spent } : a)
    await actions.taskUpdate.run({ id, task: { state: 'done', attempts: marked } })

    to[art.delivered ? 'good' : 'warn'](
      `#${task.number} done — ${outcome.state}${outcome.exit === undefined ? '' : ` (exit ${outcome.exit})`} — ${art.summary}`)
    // Said as one line rather than left in the record, because the record is
    // read when somebody already suspects something; this is what tells them to.
    to.info(`#${task.number} took ${secs(spent.total)} — ${Object.entries(spent)
      .filter(([k]) => k !== 'total').map(([k, v]) => `${k} ${secs(v)}`).join(', ')}`)
  } finally {
    // ALWAYS, and in this order. A machine left on, holding a credential, is
    // the failure that costs something: the credential outlives the task in a
    // snapshot, and the machine is out of service until a person notices.
    await putAway(actions, log, machine)
    busyWith.delete(machine)
  }
}

// Off, clean, on, and dialled in.
async function bringUp (actions, to, machine) {
  const before = (await actions.vmList.run({})).vms.find(v => v.name === machine)
  if (!before) throw new Error(`"${machine}" is gone`)

  if (before.running) {
    to.info('shutting it down so it can be made clean')
    await actions.vmStop.run({ name: machine, force: true })
    await settle(actions, to, machine, v => !v.running, 120000, 'it to stop', 15000)
  }

  // Rolled back only if it is not already there.
  //
  // putAway leaves a machine ON its base snapshot precisely so it is clean for
  // the next task, and this then restored the same snapshot again five seconds
  // later -- the same operation twice, back to back, on a machine VirtualBox had
  // only just finished restoring. That is the shape of a race, and it produced
  // one: a machine that started to a black screen and never booted.
  //
  // The check is cheap and the skip is safe: `current` is what VirtualBox says
  // the machine is sitting on, not what this app believes.
  const at = await actions.vmSnapshots.run({ name: machine })
  if (at.current === before.baseSnapshot && !before.running) {
    to.info(`already clean at "${before.baseSnapshot}"`)
  } else {
    to.info(`rolling back to "${before.baseSnapshot}"`)
    await actions.vmSnapshotRestore.run({ name: machine, title: before.baseSnapshot })
  }

  to.info('starting it')
  await actions.vmStart.run({ name: machine })
  // Started is not ready. Everything that talks to a guest refuses until it has
  // dialled in, and a machine boots for a minute or two -- so this is the step
  // most worth counting out loud, and the one that was silent for five minutes
  // while a machine sat at a cursor.
  await settle(actions, to, machine, v => v.connected, 6 * 60000, 'it to dial in', 60000)
}

// Back to its natural state: off, clean, holding nothing.
//
// Never allowed to throw. It runs in a finally, and a failure to tidy up must
// not replace the error that caused it -- losing the real reason is how a
// machine ends up left on AND nobody knowing why.
async function putAway (actions, log, machine) {
  const to = log.on('queue', machine)

  // Taken back while the machine can still be spoken to. The rollback below
  // would remove the file anyway, but a machine that fails to shut down would
  // then sit there holding a live credential -- and the point of taking it back
  // is that it stops existing on that disk, not that the registry stops saying
  // so.
  try {
    await actions.vmCredentialsForget.run({ name: machine })
  } catch (e) { to.info(`its credential was already gone: ${e.message}`) }

  // The button first, then the plug.
  //
  // `vmStop` presses the ACPI power button, which is right for a machine with an
  // operating system on it and useless for one that never got that far -- there
  // is nothing running to receive the press. A machine that failed to boot
  // therefore sat "running" for the whole timeout and was then rolled back while
  // still running, which fails too, and the machine stayed out of the pool.
  //
  // Waiting a short time and then pulling the plug is safe HERE in a way it
  // would not be elsewhere: this machine is about to be rolled back to a
  // snapshot, so an unfinished write is discarded either way.
  try {
    await actions.vmStop.run({ name: machine })
    await settle(actions, to, machine, v => !v.running, 45000, 'it to shut down', 15000)
  } catch {
    to.warn('it did not answer the power button; pulling the plug')
    try {
      await actions.vmStop.run({ name: machine, force: true })
      await settle(actions, to, machine, v => !v.running, 60000, 'it to stop', 5000)
    } catch (e) { to.warn(`could not stop it at all: ${e.message}`) }
  }

  // ROLLED BACK AT REST, and this is what makes the pool work at all.
  //
  // A machine that has finished a task still CLAIMS that task's branch, and a
  // claimed branch means "not free" -- correctly, because a machine somebody set
  // up by hand must not be taken from under them. So without this the queue
  // deadlocks after exactly one task per machine: everything it has ever used is
  // permanently ineligible, and nothing says why except a line in the state file.
  //
  // It is also what "clean" means when the natural state is off. Between tasks a
  // machine holds no branch, no credential, and none of the last worker's
  // leavings -- so the next task starts from a known disk rather than from
  // whatever the last one happened to leave.
  try {
    const vm = (await actions.vmList.run({})).vms.find(v => v.name === machine)
    if (vm && vm.baseSnapshot && !vm.running) {
      await actions.vmSnapshotRestore.run({ name: machine, title: vm.baseSnapshot })
      to.good(`off again, rolled back to "${vm.baseSnapshot}", free for the next task`)
    } else {
      to.warn('could not roll it back, so it stays out of the pool until somebody does')
    }
  } catch (e) { to.warn(`could not roll it back: ${e.message}`) }
}

// ---- waiting -----------------------------------------------------------

const wait = ms => new Promise(r => setTimeout(r, ms))

const secs = ms => `${Math.round(ms / 1000)}s`

// COUNTING OUT LOUD WHILE NOTHING HAPPENS.
//
// Every long step here is invisible from outside: a machine boots, or a worker
// thinks, and the dashboard says one line at the start and one at the end. In
// between there is no way to tell "still going" from "stuck", and the two want
// opposite responses -- wait, or go and look. This afternoon that gap was five
// minutes of a machine sitting at a black screen with nothing said about it.
//
// So a wait says how long it has been waiting, and says it louder once it has
// gone past what the step USUALLY takes. `usual` is the interesting number, not
// the timeout: a timeout is the point at which we give up, which is deliberately
// generous, and a step running four times its normal length is worth knowing
// about long before that.
//
// Cheap on purpose -- one line every 30 seconds, into the same live log as
// everything else. A progress bar nobody is watching is not the point; a
// timestamped trail somebody can read afterwards is.
function ticking (to, what, { usual = 0, every = 30000 } = {}) {
  const began = Date.now()
  let said = 0
  const timer = setInterval(() => {
    const gone = Date.now() - began
    if (gone - said < every) return
    said = gone
    if (usual && gone > usual * 2) to.warn(`still waiting for ${what} — ${secs(gone)}, and it usually takes about ${secs(usual)}`)
    else to.info(`waiting for ${what} — ${secs(gone)}`)
  }, 5000)
  if (timer.unref) timer.unref()
  return {
    done: () => {
      clearInterval(timer)
      const gone = Date.now() - began
      if (usual && gone > usual * 2) to.warn(`${what}: ${secs(gone)}, about ${Math.round(gone / usual)}x the usual ${secs(usual)}`)
      return gone
    }
  }
}

async function settle (actions, to, machine, ok, timeout, what, usual) {
  const deadline = Date.now() + timeout
  const tick = ticking(to, what, { usual })
  try {
    for (;;) {
      const vm = (await actions.vmList.run({})).vms.find(v => v.name === machine)
      if (vm && ok(vm)) return vm
      if (Date.now() > deadline) {
        // Named with the elapsed time as well as the limit, because "waited 6
        // minutes" reads as a policy and "waited 6 minutes, having expected 40
        // seconds" reads as the fault it is.
        throw new Error(`Waited ${secs(Date.now() - deadline + timeout)} for ${what} and it did not happen${usual ? ` — it usually takes about ${secs(usual)}` : ''}`)
      }
      await wait(5000)
    }
  } finally { tick.done() }
}

// Until the run is over, however it ends.
//
// `lost` counts as over. A run whose process is gone is not going to produce a
// result, and waiting for one would hold a machine out of service for as long as
// the timeout -- which is the whole afternoon, on a task nobody is going to get
// an answer to.
async function waitForRun (actions, to, machine, runId, hours = 6) {
  const deadline = Date.now() + hours * 3600000
  // No `usual` here, and that is the honest answer: a task is as long as the
  // work is, and a five-minute one and a two-hour one are both ordinary. What
  // can be said is how long it HAS been, which is what somebody deciding whether
  // to go and look actually needs.
  const tick = ticking(to, `${runId} to finish`, { every: 60000 })
  try {
    for (;;) {
      const { runs } = await actions.vmRuns.run({ name: machine })
      const mine = (runs || []).find(r => r.id === runId)
      if (mine && mine.state !== 'running') return mine
      if (!mine) return { state: 'gone' }
      if (Date.now() > deadline) {
        to.warn(`giving up on ${runId} after ${hours} hours; the machine is being put away`)
        return { state: 'abandoned' }
      }
      await wait(15000)
    }
  } finally { tick.done() }
}

// ---- picking up after a restart ---------------------------------------

// A task left mid-flight when the dashboard stopped.
//
// The dashboard is restarted for every change to it, and a task that was running
// at that moment is not finished -- but nothing in this process knows about it
// any more. Left alone it would sit in `given` for ever while its machine stayed
// on, holding a credential, out of service and looking busy.
//
// Not resumed, because the worker itself is still going or already gone and
// neither can be re-entered from here. What happens is honest: the run is waited
// on if it is still alive, and the machine is put away either way.
async function adopt (actions, log) {
  const { tasks } = await actions.tasks.run({})

  // A task that was being SET UP when this stopped never became a run.
  //
  // It sat in `given` with no run id, which made it invisible to everything: the
  // queue only looks at `queued`, adoption only looks for a run to wait on, and
  // the board showed it working with no worker anywhere. Two of them accumulated
  // in one afternoon, both from restarting the dashboard while a machine was
  // booting.
  //
  // Put back in the queue rather than marked done, and the difference is real:
  // nothing was dispatched, so no work happened and there is nothing to judge.
  // Re-queueing loses nothing and re-running it is exactly what was wanted.
  for (const t of tasks.filter(x => x.state === 'given' && !x.run)) {
    log.on('queue').warn(`#${t.number} was being set up when this stopped, and never started — back in the queue`)
    await actions.taskUpdate.run({ id: t.id, task: { state: 'queued', machine: null } }).catch(() => {})
  }

  const midFlight = tasks.filter(t => t.state === 'given' && t.machine && t.run)
  for (const task of midFlight) {
    if (busyWith.has(task.machine)) continue
    busyWith.set(task.machine, `#${task.number}`)
    const to = log.on('queue', task.machine)
    to.warn(`#${task.number} was in flight when this restarted; picking it back up`)
    ;(async () => {
      try {
        const { vms } = await actions.vmList.run({})
        const vm = vms.find(v => v.name === task.machine)
        if (vm && vm.connected) {
          await waitForRun(actions, to, task.machine, task.run)
          await actions.taskProgress.run({ id: task.id }).catch(() => {})
        }
        const art = await actions.taskArtifact.run({ id: task.id })
        await actions.taskUpdate.run({ id: task.id, task: { state: 'done' } })
        to[art.delivered ? 'good' : 'warn'](`#${task.number} done — ${art.summary}`)
      } finally {
        await putAway(actions, log, task.machine)
        busyWith.delete(task.machine)
      }
    })().catch(e => to.bad(e.message))
  }
}

const state = () => ({ inFlight: [...busyWith.entries()].map(([machine, task]) => ({ machine, task })) })

module.exports = { begin, stop, tick, availability, state, busyWith, TICK }

'use strict'

// Planned tasks, declared the way tests are declared.
//
// These are the drills from TEST-PLAN.md, which were prose until now: a person
// read them and typed the commands. Prose cannot report a status, cannot be
// offered in a window, and rots quietly against the code it describes. Declared
// with describe/it they can be listed, chosen, run one at a time, and reported
// on as they go.
//
// THEY DRIVE THE ACTIONS, not the modules underneath. Every drill is handed
// `okc`, which is the same action table the window and the command line use --
// so a drill exercises what a person exercises, including the refusals, rather
// than proving something about code that nothing calls that way.
//
// HALF OF THEM PASS BY BEING REFUSED, which is why `assert.refuses` exists. The
// question is never whether the flow can be driven, it is whether it can be
// driven wrong -- and a guard is not a guard until something has been refused by
// it. Twice in this project a guard was written, reviewed, and open.
//
// A drill that cannot run says so as a failure rather than passing quietly.
// "There was no machine to try it on" is not evidence that a rule holds, and a
// green tick for it is worse than a red one.

const { describe, it } = require('./harness')

// A name nothing else will be using. Not random -- these have to be findable and
// removable afterwards by somebody reading the repository, and a uuid in a branch
// list tells them nothing about where it came from.
const scratch = what => `drill/${what}-${new Date().toISOString().replace(/[^0-9]/g, '').slice(8, 14)}`

describe('guards — the things that must be refused', () => {
  it('a task with nowhere to deliver is refused', async ({ okc, assert }) => {
    await assert.refuses(
      () => okc('taskCreate', { task: { title: 'no branch', brief: 'anything' } }),
      'branch',
      'A task with no branch has no artifact and could never be judged')
  })

  it('a contract that is not there is refused', async ({ okc, assert }) => {
    await assert.refuses(
      () => okc('taskCreate', { task: { title: 'bad contract', brief: 'anything', branch: scratch('contract'), contract: 'C:/nothing/here.md' } }),
      'no contract at',
      'A contract that silently fails to load leaves a worker with no rules while everything reports success')
  })

  it('a verdict on a branch with nothing on it is refused', async ({ okc, assert }) => {
    const branch = scratch('empty')
    const task = await okc('taskCreate', { task: { title: 'nothing delivered', brief: 'anything', branch } })
    try {
      await assert.refuses(
        () => okc('taskJudge', { id: task.id, verdict: 'accept', note: 'should not be possible' }),
        'nothing to judge',
        'A judgement of nothing is indistinguishable afterwards from a judgement of something')
    } finally {
      await okc('taskRemove', { id: task.id })
    }
  })

  it('a rejection with no reason is refused', async ({ okc, assert }) => {
    // Checked on a delivered task if there is one, because the empty-branch
    // refusal above would otherwise be the thing that fires and this would pass
    // for the wrong reason.
    const { tasks } = await okc('tasks')
    const delivered = tasks.find(t => t.delivered)
    assert.ok(delivered, 'This drill needs a task whose branch has something on it; there is none. Run the round trip first.')
    await assert.refuses(
      () => okc('taskJudge', { id: delivered.id, verdict: 'reject', note: '' }),
      'why',
      'A rejection with no reason is sent to a worker that cannot ask what was wrong')
  })

  it('a machine holding a credential cannot be snapshotted', async ({ okc, assert }) => {
    const { vms } = await okc('vmList')
    const holding = vms.find(v => v.holdsCredential)
    assert.ok(holding, 'This drill needs a machine holding a credential; none is. Hand one out with vmCredentialsPut first.')
    await assert.refuses(
      () => okc('vmBaseSnapshot', { name: holding.name, title: 'drill-should-refuse' }),
      'holding a worker credential',
      'A snapshot keeps a copy of the token for as long as the snapshot exists')
  })

  it('a signed-out machine is not given work', async ({ okc, assert, log }) => {
    const { vms } = await okc('vmList')

    // Arranged rather than waited for.
    //
    // The first version required a connected machine that happened to be signed
    // out, and on a working host there is never one -- so the drill reported
    // "there was nothing to try it on", which is not evidence and sat in the
    // results looking like a fault. A drill that only runs when the world
    // happens to suit it is a drill that never runs.
    //
    // Safe to arrange: the credential is kept on this host, sealed, so taking it
    // off a machine loses nothing and putting it back is one call. The finally
    // is not optional -- leaving a machine signed out would break the next thing
    // to use it, and blame something else.
    const target = vms.find(v => v.connected && v.holdsCredential) || vms.find(v => v.connected)
    assert.ok(target, 'This drill needs a machine dialled in; none is.')

    const held = !!(target.holdsCredential)
    if (held) {
      log(`taking ${target.name}'s credential for the duration, and putting it back afterwards`)
      await okc('vmCredentialsForget', { name: target.name })
    }
    try {
      await assert.refuses(
        () => okc('vmDispatch', { name: target.name, task: 'anything at all' }),
        'signed out',
        'Otherwise it fails as an api error minutes later, after a workspace has been laid out')
    } finally {
      if (held) await okc('vmCredentialsPut', { name: target.name })
    }
  })

  it('a machine is not moved off the branch it is on', async ({ okc, assert }) => {
    const { vms } = await okc('vmList')
    const on = vms.find(v => v.connected && v.branch)
    assert.ok(on, 'This drill needs a connected machine already set up on a branch; there is none.')
    await assert.refuses(
      () => okc('vmWorkspace', { name: on.name, branch: scratch('elsewhere') }),
      'stays there until it is clean',
      'Switching is how half-finished work stops being anywhere')
  })

  it('a branch already claimed is not handed to a second machine', async ({ okc, assert }) => {
    const { vms } = await okc('vmList')
    const claimed = vms.find(v => v.branch)

    // The second machine must be on NO branch of its own, and that is the whole
    // subtlety here rather than a detail.
    //
    // Two rules can refuse this, and only one of them is the rule under test. A
    // machine that is already on a branch is refused for being on it -- "stays
    // there until it is clean" -- and that refusal fires first, before the claim
    // is ever consulted. The drill passed on a bare "did it throw", and what it
    // proved was a different rule than the one it names.
    //
    // Not arranged, unlike the credential drill. Releasing a claim means rolling
    // a machine back to a snapshot from before the branch, which DISCARDS
    // whatever is on it -- a drill may not decide that somebody's work is worth
    // less than a green tick.
    const free = vms.find(v => v.connected && !v.branch && v.name !== (claimed || {}).name)
    assert.ok(claimed, 'This drill needs a machine claiming a branch; none is.')
    assert.ok(free, 'This drill needs a connected machine that is on no branch, and there is none. It will not make one: the only way off a branch is a rollback, and that discards whatever is on it.')

    await assert.refuses(
      () => okc('vmWorkspace', { name: free.name, branch: claimed.branch }),
      'already being worked on',
      'Two machines on one branch race for the same ref and the loser\'s commits strand')
  })
})

describe('the round trip — work goes out, and something comes back', () => {
  // These take minutes rather than seconds: they set up a workspace, start a
  // worker, and wait for it. Run them deliberately.

  it('a worker delivers a branch, and it can be read here', async ({ okc, assert, log, machine, waitFor }) => {
    assert.ok(machine, 'Say which machine this runs on.')
    const branch = scratch('delivers')
    const task = await okc('taskCreate', {
      task: {
        title: 'Drill: deliver a branch',
        branch,
        brief: 'In the repository local-repo-a, add one line to readme.md that reads exactly: delivered by a drill. Commit it with a clear message and push it to origin on the branch you are on. Do not change any other file.'
      }
    })

    log(`giving ${task.id} to ${machine} on ${branch}`)
    await okc('taskGive', { id: task.id, name: machine })

    const art = await waitFor(
      () => okc('taskArtifact', { id: task.id }),
      a => a.delivered,
      { what: 'the branch to arrive', minutes: 10 })

    assert.ok(art.delivered, 'Nothing arrived on the branch')
    assert.ok(art.commits >= 1, `Expected at least one commit, got ${art.commits}`)
    log(`delivered: ${art.summary}`)
  })

  it('a worker cannot push to the default branch', async ({ okc, assert, log, machine, waitFor }) => {
    assert.ok(machine, 'Say which machine this runs on.')
    const branch = scratch('protected')

    // The instruction is blunt on purpose. Asked vaguely, a worker does the
    // sensible thing instead, the push never reaches the hook, and the drill
    // proves nothing while looking like it passed.
    const task = await okc('taskCreate', {
      task: {
        title: 'Drill: push to the default branch',
        branch,
        brief: 'In the repository local-repo-a, add a line to readme.md saying: this should never land. Then run git checkout master, commit the change on master, and run git push origin master. Do not push any other branch. If the push is refused, report exactly what the server said and stop.'
      }
    })

    const before = await okc('gitBranches')
    log(`giving ${task.id} to ${machine}; the default branch must not move`)
    await okc('taskGive', { id: task.id, name: machine })

    // Waited on the RUN rather than on the artifact, because the pass here is
    // that nothing is ever delivered -- and waiting for something that must not
    // arrive would only ever time out.
    await waitFor(
      () => okc('vmRuns', { name: machine }),
      r => (r.runs || []).some(x => x.state !== 'running'),
      { what: 'the worker to finish', minutes: 10 })

    const art = await okc('taskArtifact', { id: task.id })
    assert.equal(art.delivered, false, 'Something arrived on a branch the worker was told not to use')

    // The same number, twice. This is the whole assertion: a rule about what may
    // not land is only checked by comparing where the branch was with where it
    // is, and everything else -- the refusal message, the exit code, what the
    // worker said it did -- is somebody's account of that.
    const after = await okc('gitBranches')
    const moved = (after.defaultHeads || []).filter(now => {
      const was = (before.defaultHeads || []).find(b => b.repo === now.repo)
      return was && was.at !== now.at
    })
    assert.equal(moved.length, 0, `The default branch moved in ${moved.map(m => m.repo).join(', ')} — the hook did not hold`)

    log('refused, and the default branch did not move')
    await okc('taskRemove', { id: task.id })
  })
})

'use strict'

// The machines you have, as editable configuration rather than something baked
// in. Add and remove them from the page; this is where they are kept.

const fs = require('node:fs')
const path = require('node:path')
const log = require('../core/log')

const STATE = process.env.OKC_STATE || path.join(__dirname, '..', 'state')
const FILE = path.join(STATE, 'machines.json')

// This machine always exists and cannot be removed. Without it the page opens
// with nothing to act on, and the one machine everybody has is the one nobody
// should have to configure.
const HERE = { id: 'here', name: 'This machine', kind: 'local', fixed: true }

function all () {
  if (!fs.existsSync(FILE)) return [HERE]
  let saved = []
  try {
    // Same tolerance as the machine registry: a byte-order mark or a lone object
    // should not read as "there are none".
    const data = JSON.parse(fs.readFileSync(FILE, 'utf8').replace(/^\uFEFF/, ''))
    saved = Array.isArray(data) ? data : [data]
  } catch (e) {
    log.on('machines').bad(`${FILE} could not be read (${e.message}).`)
  }
  return [HERE, ...saved.filter(m => m.id !== 'here')]
}

const save = list => {
  fs.mkdirSync(STATE, { recursive: true })
  fs.writeFileSync(FILE, JSON.stringify(list.filter(m => !m.fixed), null, 2))
}

const get = id => {
  const m = all().find(m => m.id === id)
  if (!m) throw new Error(`No machine called "${id}"`)
  return m
}

function add (m) {
  if (!m.name || !m.name.trim()) throw new Error('Give the machine a name.')
  const id = (m.id || m.name).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
  if (!id) throw new Error('That name has no letters or numbers in it.')
  if (all().some(x => x.id === id)) throw new Error(`There is already a machine called "${id}".`)
  if (m.kind === 'ssh' && !m.host) throw new Error('An ssh machine needs a host, like user@address.')

  const machine = {
    id,
    name: m.name.trim(),
    kind: m.kind === 'ssh' ? 'ssh' : 'local',
    host: m.host || '',
    path: m.path || '',
    editor: m.editor || '',
    vm: m.vm && m.vm.name ? { provider: 'virtualbox', name: m.vm.name } : null,
    provision: Array.isArray(m.provision) ? m.provision : []
  }
  save([...all(), machine])
  log.on('machines').good(`Added machine "${machine.name}"`)
  return machine
}

function update (id, patch) {
  const list = all()
  const m = list.find(x => x.id === id)
  if (!m) throw new Error(`No machine called "${id}"`)
  if (m.fixed && (patch.kind || patch.host)) throw new Error('This machine cannot be turned into something else.')
  Object.assign(m, patch, { id: m.id, fixed: m.fixed })
  save(list)
  log.on('machines', id).info(`Changed "${m.name}"`)
  return m
}

function remove (id) {
  const m = get(id)
  if (m.fixed) throw new Error('This machine cannot be removed.')
  save(all().filter(x => x.id !== id))
  log.on('machines', id).info(`Removed "${m.name}". Nothing on it was touched.`)
  return { removed: id }
}

module.exports = { all, get, add, update, remove }

'use strict'

// Provisioning: the steps that get a machine ready, run in order, streaming into
// the live log.
//
// The steps are configuration on the machine, not code in here. This file knows
// how to run a list and when to stop; it never knows what any step is for.

const log = require('../core/log')
const { at } = require('./run')

// Stops at the first failure. A later step almost always assumes an earlier one
// worked, so continuing past a failure produces a second, confusing error about
// something that was never the problem.
async function provision (machine, steps) {
  const list = steps || machine.provision || []
  const to = log.on('provision', machine.id)

  if (!list.length) {
    to.warn(`"${machine.name}" has no setup steps yet. Add them in its settings.`)
    return { machine: machine.id, steps: [], ok: true }
  }

  to.info(`Setting up "${machine.name}" — ${list.length} step${list.length === 1 ? '' : 's'}`)
  const done = []

  for (const [i, step] of list.entries()) {
    const label = step.name || step.run
    to.info(`Step ${i + 1} of ${list.length}: ${label}`)
    try {
      await at(machine, step.run, { tags: ['provision', machine.id], cwd: step.cwd })
      done.push({ name: label, ok: true })
      to.good(`Step ${i + 1} done`)
    } catch (e) {
      done.push({ name: label, ok: false, why: e.message })
      to.bad(`Step ${i + 1} failed: ${e.message}`)
      to.warn(`Stopped here. The steps after this one were not run, because they would assume this one worked.`)
      return { machine: machine.id, steps: done, ok: false, stoppedAt: i + 1 }
    }
  }

  to.good(`"${machine.name}" is set up.`)
  return { machine: machine.id, steps: done, ok: true }
}

// Is this machine reachable at all? Asked before setting up, because "step 1
// failed" is a worse answer than "that address does not answer".
async function reach (machine) {
  const to = log.on('provision', machine.id)
  try {
    const who = await at(machine, machine.kind === 'ssh' ? 'whoami && uname -a' : 'echo ok',
      { tags: ['provision', machine.id], quiet: true })
    to.good(`"${machine.name}" answers: ${who.split('\n').join(' · ')}`)
    return { reachable: true, as: who }
  } catch (e) {
    to.bad(`"${machine.name}" did not answer: ${e.message}`)
    return { reachable: false, why: e.message }
  }
}

module.exports = { provision, reach }

'use strict'

// Runs a command somewhere, and says so in the log while it runs.
//
// "Somewhere" is either this machine or one reached over ssh. Callers do not
// branch on which -- that is the whole point of a machine being a value rather
// than a special case.

const { spawn } = require('node:child_process')
const log = require('../core/log')

// Streams output as it arrives rather than returning it at the end, because a
// long step with nothing on screen is indistinguishable from a hung one.
function run (cmd, args, { cwd, tags = [], quiet = false } = {}) {
  const to = log.on(...tags)
  if (!quiet) to.info(`$ ${[cmd, ...args].join(' ')}`)

  return new Promise((resolve, reject) => {
    let child
    try {
      child = spawn(cmd, args, { cwd, shell: false })
    } catch (e) {
      to.bad(e.message)
      return reject(e)
    }

    let out = ''
    let err = ''
    child.stdout.on('data', d => { out += d; if (!quiet) to.out(String(d)) })
    child.stderr.on('data', d => { err += d; if (!quiet) to.out(String(d)) })

    child.on('error', e => {
      to.bad(e.code === 'ENOENT' ? `${cmd} is not installed, or not where this expected it` : e.message)
      reject(e)
    })
    child.on('close', code => {
      if (code === 0) return resolve(out.trim())
      const why = (err || out).trim().split('\n').slice(-3).join(' ') || `exit code ${code}`
      to.bad(why)
      reject(new Error(why))
    })
  })
}

// The same call, wherever the machine is. An ssh machine gets the command handed
// to a shell on the far side; this machine runs it directly.
const at = (machine, script, opts = {}) => machine.kind === 'ssh'
  ? run('ssh', [machine.host, opts.cwd ? `cd ${opts.cwd} && ${script}` : script],
      { ...opts, cwd: undefined, tags: [...(opts.tags || []), 'ssh', machine.id] })
  : run(process.platform === 'win32' ? 'cmd' : 'sh',
      process.platform === 'win32' ? ['/c', script] : ['-c', script],
      { ...opts, tags: [...(opts.tags || []), machine.id] })

module.exports = { run, at }

'use strict'

// Opening the work in VS Code, wherever the work is.
//
// The step between "the machine is ready" and "I am editing in it". Without it a
// person has to find the machine's address, and type it more than once.
//
// Everything here that looks like superstition was measured on a real
// workstation, because the obvious version of this file produces a button that
// silently does nothing:
//
//   * `code` is frequently not on PATH AT ALL, and Insiders is a different
//     binary with a different name -- `code-insiders`. Looking only for `code`
//     finds nothing on a machine that has an editor installed and working.
//   * Node REFUSES to spawn a `.cmd` directly. It throws EINVAL, and throws it
//     SYNCHRONOUSLY -- before any callback and before any 'error' event, so
//     error handling written the normal way never runs. That is the
//     CVE-2024-27980 mitigation, and it fails before the arguments matter.
//   * Spawning successfully is NOT the same as opening. `cmd.exe` starts
//     perfectly well and only then reports that what it was asked to run does
//     not exist, so resolving on spawn reports success for a button that did
//     nothing.

const fs = require('node:fs')
const path = require('node:path')
const { execFile } = require('node:child_process')
const log = require('../core/log')

// Insiders first. Both are found, so nothing needs configuring either way, but
// where both are installed the preference has to be fixed rather than
// incidental: a button that quietly changes which editor it opens the day
// another one is installed is worse than one that always picks the same and can
// be told otherwise.
const EDITORS = [
  ['Microsoft VS Code Insiders', 'code-insiders'],
  ['Microsoft VS Code', 'code']
]

const there = p => { try { return fs.existsSync(p) } catch { return false } }

// Where the editor actually is, and how that was decided -- the second half
// matters when the answer is wrong.
function discover (configured) {
  if (configured) {
    if (!there(configured) && !/[\\/]/.test(configured)) return { command: configured, from: 'configured, on PATH' }
    if (!there(configured)) throw new Error(`The editor is set to ${configured}, and there is nothing there.`)
    return { command: configured, from: 'configured' }
  }

  const roots = [
    process.env.LOCALAPPDATA && path.join(process.env.LOCALAPPDATA, 'Programs'),
    process.env.ProgramFiles,
    process.env['ProgramFiles(x86)']
  ].filter(Boolean)

  for (const [dir, bin] of EDITORS) {
    for (const root of roots) {
      for (const ext of ['.cmd', '']) {
        const candidate = path.join(root, dir, 'bin', `${bin}${ext}`)
        if (there(candidate)) return { command: candidate, from: 'found where it installs' }
      }
    }
  }
  for (const p of ['/usr/bin/code', '/usr/local/bin/code', '/snap/bin/code', '/usr/bin/code-insiders']) {
    if (there(p)) return { command: p, from: 'found where it installs' }
  }
  // Somebody may still have put it on PATH under either name.
  return { command: process.platform === 'win32' ? 'code.cmd' : 'code', from: 'guessed — not found where it installs' }
}

// `vscode-remote://ssh-remote+<user>@<address><absolute path>`
//
// ONE string for the far end, not a user and a host to be joined here. An ssh
// machine is already stored as `user@address`, and a virtual machine's is built
// from what it reported when it dialled in -- so joining them in this file would
// mean one of the two callers producing `user@user@address`, which fails as an
// unreachable host rather than as anything that names the mistake.
//
// user@address rather than a name from ~/.ssh/config, because a config entry is
// a second place the machine's address would live and it goes stale the first
// time the address moves. This form needs nothing on the host but the key, which
// first-boot.sh already installed.
const folderUri = (remote, dir) =>
  `vscode-remote://ssh-remote+${encodeURIComponent(remote)}${dir.startsWith('/') ? '' : '/'}${dir}`

// Windows will not start a .cmd from node directly; it goes through cmd.exe.
//
// `{ shell: true }` is the other way out and is NOT used: the editor installs to
// a path with spaces in it, and the shell splits on them -- so it would need
// quoting done by hand, which is the thing that keeps going wrong here. Through
// cmd.exe, node quotes each argument and no shell parses the path at all.
function launchSpec (command, args) {
  if (process.platform === 'win32' && /\.(cmd|bat)$/i.test(command)) {
    return { file: process.env.COMSPEC || 'cmd.exe', argv: ['/c', command, ...args] }
  }
  return { file: command, argv: args }
}

// Open a folder: on this machine when there is no host, over VS Code's own
// remote when there is. One folder, not a generated multi-root workspace -- VS
// Code finds every .git inside a folder and shows each repository's status, so
// opening the tree that holds them gives all of them with no file to generate.
// It also means the editor never needs to know what the work spans.
function open ({ dir, remote, command, tags = [] }) {
  if (!dir) throw new Error('There is no folder to open.')

  const { command: exe, from } = discover(command)
  const args = remote
    ? ['--folder-uri', folderUri(remote, dir), '--new-window']
    : [dir, '--new-window']
  const spec = launchSpec(exe, args)

  const to = log.on('editor', ...tags)
  const attempted = `${spec.file} ${spec.argv.map(a => (/\s/.test(a) ? `"${a}"` : a)).join(' ')}`
  to.info(`Opening ${dir}${remote ? ` on ${remote}` : ''} in VS Code`)

  // An errno is not something a person can act on, and this is the button where
  // they meet the system. So a failure says what was run and what that
  // particular failure usually means.
  const explain = err => {
    const why = err.code === 'EINVAL' && process.platform === 'win32'
      ? ' — Windows will not start a .cmd directly; this should have gone through cmd.exe.'
      : err.code === 'ENOENT'
        ? ` — that was not found. The editor was ${from}.`
        : ''
    const said = err.detail ? `\n  it said: ${err.detail}` : ''
    return new Error(`Could not start the editor.\n  tried: ${attempted}\n  ${err.code || 'failed'}${why}${said}`)
  }

  return new Promise((resolve, reject) => {
    let settled = false
    const finish = (fn, value) => { if (!settled) { settled = true; fn(value) } }

    let child
    try {
      child = execFile(spec.file, spec.argv, { windowsHide: true }, (err, stdout, stderr) => {
        if (err && err.code) {
          const detail = String(stderr || stdout || '').trim().split('\n')[0]
          to.bad(`the editor did not start: ${detail || err.code}`)
          finish(reject, explain(Object.assign(err, { detail })))
        }
      })
    } catch (err) {
      // The EINVAL path. Thrown synchronously, so it reaches neither the
      // callback nor the 'error' event; here is the only place it can become
      // something readable.
      to.bad(err.message)
      return finish(reject, explain(err))
    }

    child.on('error', err => { to.bad(err.message); finish(reject, explain(err)) })

    // A grace window rather than waiting for exit: the editor outlives this call
    // by design -- the dashboard opened a window, it does not own it -- so
    // waiting for it to close would hang forever. A launcher either fails within
    // milliseconds or has genuinely started.
    const grace = setTimeout(() => {
      to.good('VS Code was asked to open it.')
      finish(resolve, { opened: dir, on: remote || null, using: exe, found: from })
    }, 1500)

    child.on('exit', code => {
      if (code === 0) {
        clearTimeout(grace)
        to.good('VS Code was asked to open it.')
        finish(resolve, { opened: dir, on: remote || null, using: exe, found: from })
      }
      // A non-zero exit is handled by the execFile callback, which has the
      // output needed to explain it.
    })
    if (typeof child.unref === 'function') child.unref()
  })
}

// The machines kept as configuration: this one, or one reached over ssh, where
// the far end is already stored as `user@address`.
const openOn = (machine, where) => {
  const dir = where || machine.path
  if (!dir) throw new Error(`There is no folder to open for "${machine.name}". Set one in its settings.`)
  return open({
    dir,
    remote: machine.kind === 'ssh' ? machine.host : null,
    command: machine.editor,
    tags: [machine.id]
  })
}

module.exports = { open, openOn, discover, folderUri }

'use strict'

// One long thing at a time, per machine.
//
// Snapshotting a machine shuts it down, snapshots it and starts it again.
// Installing wipes its disk and drives an installer for half an hour. Restoring
// throws its disk away. Each of those is several VirtualBox commands with a
// machine in an unfinished state in between -- and VirtualBox answers a second
// one during that window with a session lock error, which arrives as a wall of
// COM text describing an interface nobody asked about.
//
// So a second one is refused HERE, where the refusal can say which machine is
// busy and with what. Not queued: waiting would mean a command that appears to
// hang for twenty-five minutes, and the honest answer to "start this machine"
// while it is being installed is no, not later.
//
// READS ARE NEVER BLOCKED. Asking what a machine's state is, or what it has on
// screen, is exactly what somebody does when something is taking a long time,
// and a lock that stops you looking is a lock that gets worked around.

const doing = new Map()   // machine name -> what it is in the middle of

const what = name => doing.get(name) || null

// Refuses rather than waits, and names both machines involved -- "it is busy" is
// not actionable, "runner1 is being installed" is.
function claim (name, job) {
  const already = doing.get(name)
  if (already) {
    throw new Error(`"${name}" is already ${already}. Wait for that to finish — one of these at a time, because they leave the machine half-way in between and VirtualBox will refuse the second with an error about a session lock.`)
  }
  doing.set(name, job)
}

const release = name => doing.delete(name)

// Claim, run, release whatever happens. A job that threw still has to let go,
// or one failure leaves a machine permanently unusable with nothing running.
async function during (name, job, fn) {
  claim(name, job)
  try {
    return await fn()
  } finally {
    release(name)
  }
}

module.exports = { during, claim, release, what, all: () => [...doing.entries()].map(([name, job]) => ({ name, job })) }

'use strict'

// Reading the Claude session inside a runner.
//
// A machine runs Claude Code; Claude Code appends everything it does to a
// transcript on that machine's disk. That file is the handle -- the same one a
// supervising session uses to watch a sibling on the host, except here it is on
// the other side of the channel.
//
// STRICTLY READ-ONLY, and that is a rule rather than an accident of the current
// implementation. A supervisor that writes into the tree a worker is editing is
// how one session's notes end up inside another's commit, which is a real thing
// that happened here and is written down in the legacy PLAN as the day's worst
// coordination failure. Everything below opens files and prints.
//
// DELTAS, NOT DUMPS. The bookmark is a line number in the transcript, and the
// caller passes back the one it was given. A watcher that re-reads from the top
// spends its context re-deriving what it already reported -- which for an agent
// is the whole cost, and for a long-running task is most of it.

const secret = require('../core/secret')

const CLIP = 200

// Sent to the machine and read by node there. Fed through stdin as a heredoc so
// nothing has to be installed, nothing is left behind, and no quoting has to
// survive two shells.
//
// It prints ONE json object and nothing else, so a half-written line or a
// warning from the login shell cannot be mistaken for the answer -- the caller
// takes the last line that parses.
const PROGRAM = `
const fs = require('fs'), os = require('os'), path = require('path')
const MODE = process.argv[2] || 'list'
const WANT = process.argv[3] || ''
const SINCE = Number(process.argv[4] || 0)
const LIMIT = Number(process.argv[5] || 40)
const ROOT = path.join(os.homedir(), '.claude', 'projects')
const CLIP = ${CLIP}

const clip = s => { const f = String(s == null ? '' : s).replace(/\\s+/g, ' ').trim(); return f.length > CLIP ? f.slice(0, CLIP) + '\\u2026' : f }
const readLines = f => { try { return fs.readFileSync(f, 'utf8').split('\\n').filter(l => l.trim()) } catch { return [] } }
const parse = l => { try { return JSON.parse(l) } catch { return null } }

function sessions () {
  const out = []
  let projects = []
  try { projects = fs.readdirSync(ROOT, { withFileTypes: true }).filter(e => e.isDirectory()) } catch { return out }
  for (const p of projects) {
    const dir = path.join(ROOT, p.name)
    let files = []
    try { files = fs.readdirSync(dir).filter(f => f.endsWith('.jsonl')) } catch { continue }
    for (const f of files) {
      const full = path.join(dir, f)
      const lines = readLines(full)
      let title = null, last = null, cwd = null
      for (const l of lines) {
        const e = parse(l)
        if (!e) continue
        if (e.aiTitle) title = e.aiTitle
        if (e.timestamp) last = e.timestamp
        if (e.cwd) cwd = e.cwd
      }
      out.push({
        id: f.replace(/\\.jsonl$/, ''),
        project: p.name,
        cwd,
        title,
        lines: lines.length,
        last,
        idle: last ? Math.max(0, Math.round((Date.now() - Date.parse(last)) / 1000)) : null
      })
    }
  }
  return out.sort((a, b) => Date.parse(b.last || 0) - Date.parse(a.last || 0))
}

const all = sessions()

if (MODE === 'list') {
  console.log(JSON.stringify({ ok: true, sessions: all }))
  process.exit(0)
}

// A prefix matching two sessions is an error, never a guess. Silently watching
// the wrong one produces confident wrong reports, which is the failure this is
// meant to prevent rather than commit.
const hits = WANT ? all.filter(s => s.id.startsWith(WANT)) : all
if (!hits.length) { console.log(JSON.stringify({ ok: false, error: WANT ? 'no session here matching "' + WANT + '"' : 'no claude sessions on this machine' })); process.exit(0) }
if (hits.length > 1) { console.log(JSON.stringify({ ok: false, error: 'that matches ' + hits.length + ' sessions', sessions: hits })); process.exit(0) }

const s = hits[0]
const file = path.join(ROOT, s.project, s.id + '.jsonl')
const lines = readLines(file)
const from = Math.max(0, Math.min(SINCE, lines.length))
const entries = []

// What is worth a supervisor's attention, and nothing else. A tool result is
// tens of kilobytes; a read of a file it already had is not news.
const QUIET = new Set(['Read', 'Grep', 'Glob', 'TodoWrite', 'ToolSearch'])
const VERDICT = /(\\bFAIL(ED)?\\b|\\berror:|\\w*Error:|Traceback|segfault|\\bexit=[1-9]|\\bok\\b|passing|failing)/
const names = new Map()

for (let i = from; i < lines.length; i++) {
  const e = parse(lines[i])
  if (!e || (e.type !== 'user' && e.type !== 'assistant')) continue
  const at = e.timestamp || null
  const c = e.message && e.message.content
  if (typeof c === 'string') {
    if (c.trim()) entries.push({ line: i + 1, at, kind: 'said-to-it', text: clip(c) })
    continue
  }
  if (!Array.isArray(c)) continue
  for (const b of c) {
    if (b.type === 'text' && b.text && b.text.trim()) entries.push({ line: i + 1, at, kind: 'text', text: clip(b.text) })
    else if (b.type === 'tool_use') {
      if (b.id) names.set(b.id, b.name)
      if (b.name === 'AskUserQuestion') {
        entries.push({ line: i + 1, at, kind: 'asked', text: clip((b.input && b.input.questions || []).map(q => q.question).join(' | ')) })
      } else if (b.name === 'Bash') entries.push({ line: i + 1, at, kind: 'ran', text: clip(b.input && b.input.command) })
      else if (b.name === 'Edit' || b.name === 'Write' || b.name === 'NotebookEdit') {
        entries.push({ line: i + 1, at, kind: b.name === 'Write' ? 'wrote' : 'edited', text: clip(b.input && b.input.file_path) })
      } else if (!QUIET.has(b.name)) entries.push({ line: i + 1, at, kind: b.name.toLowerCase(), text: clip((b.input && (b.input.command || b.input.file_path || b.input.prompt)) || '') })
    } else if (b.type === 'tool_result') {
      const from2 = names.get(b.tool_use_id)
      if (from2 && QUIET.has(from2)) continue
      const body = typeof b.content === 'string' ? b.content : JSON.stringify(b.content == null ? '' : b.content)
      // Only the lines that carry a verdict. The rest is bulk, and carrying it
      // across is what makes a watcher expensive.
      const hot = body.split('\\n').filter(l => l.trim() && VERDICT.test(l)).slice(0, 4)
      for (const h of hot) entries.push({ line: i + 1, at, kind: 'result', text: clip(h) })
    }
  }
}

console.log(JSON.stringify({
  ok: true,
  session: { id: s.id, title: s.title, cwd: s.cwd, idle: s.idle, last: s.last, lines: lines.length },
  from,
  bookmark: lines.length,
  entries: entries.slice(-LIMIT),
  more: Math.max(0, entries.length - LIMIT)
}))
`

// Wrapped so the program reaches node through stdin rather than through the
// command line, where quoting would have to survive both this file and the
// guest's login shell.
const command = (mode, args = []) => `node - ${[mode, ...args].map(a => `'${String(a).replace(/'/g, "'\\''")}'`).join(' ')} <<'OKC_SESSION_EOF'\n${PROGRAM}\nOKC_SESSION_EOF`

// The last line that parses as json. The login shell may print anything before
// it -- a motd, an nvm notice -- and a watcher that took the first line would
// break on a machine somebody had customised.
function answer (output) {
  // REDACTED AT THE BOUNDARY, before anything is kept here.
  //
  // A worker can read its own credential -- it cannot authenticate otherwise --
  // and it runs as the user that owns the file. So a token can reach its output
  // through an env dump, a stack trace, or a stray `cat`, and this transcript is
  // pulled to the host and kept. That makes it not a moment of exposure but a
  // filing, permanently. Cleaned on the way in is the only place it can be
  // stopped; anywhere later is after it has already been written down.
  const lines = secret.redact(output).split('\n').map(l => l.trim()).filter(Boolean)
  for (let i = lines.length - 1; i >= 0; i--) {
    if (!lines[i].startsWith('{')) continue
    try { return JSON.parse(lines[i]) } catch { /* keep looking */ }
  }
  return { ok: false, error: 'the machine did not answer with anything readable' }
}

module.exports = { command, answer, CLIP }

'use strict'

// Giving a machine a task, and letting go of it.
//
// FIRE AND FORGET, on purpose. A task runs for minutes or an hour, and holding
// the channel open for it would make dispatching indistinguishable from waiting
// -- one command that appears to hang, no progress, and nothing else able to use
// the machine meanwhile. So this starts the work detached and returns a run id.
// Progress is READ afterwards, from the session transcript, which is a delta
// with a bookmark rather than a stream nobody is watching.
//
// NOTHING HERE CARRIES A CREDENTIAL, and that is a correction rather than an
// omission. The first version of this passed one as an environment assignment on
// the command that starts the run -- which the agent inherits, and can print.
//
// That is the exact interaction the design notes warn about and call easy to
// miss: transcripts are captured to this host and kept, so a credential that
// reaches agent-visible output -- an env dump, a stack trace, an error -- is
// copied out and filed by design. A worker is signed in separately, through its
// own credential file, which is Claude Code's and not something the agent is
// handed a copy of in its environment.

const path = require('node:path')

// Shell-single-quoted. Everything here crosses into a script, and a task is
// written by a person -- or by another agent -- so its shape is not this file's
// to assume.
const q = s => `'${String(s).replace(/'/g, `'\\''`)}'`

const RUNS = '$HOME/.okc-runs'

// Where a run's record lives on the machine. One directory per run: the prompt
// as it was given, the raw output, and the exit status written when it ends.
//
// Kept rather than streamed and dropped. "What actually ran" has no source but a
// record of the run -- a claim in a transcript is the agent's account of itself,
// and the two diverge.
// A heredoc ends at its delimiter, wherever that appears. Text arriving here is
// written by a person or by another agent, so "it will not contain that line" is
// an assumption about somebody else's prose -- and the failure is not an error
// but the rest of the text being executed as shell.
function heredoc (path, body, tag) {
  if (new RegExp(`^${tag}$`, 'm').test(body)) {
    throw new Error(`That text contains a line reading exactly "${tag}", which is the marker used to send it to the machine. Change that line.`)
  }
  return `cat > ${path} <<'${tag}'\n${body}\n${tag}`
}

// Where a run's record lives on the machine. One directory per run: the prompt
// as it was given, the rules it was given with, the script that ran, its output,
// and the status written when it ends.
//
// Kept rather than streamed and dropped. "What actually ran" has no source but a
// record of the run -- a claim in a transcript is the agent's account of itself,
// and the two diverge.
function script ({ id, task, folder, contract, resume }) {
  const dir = `${RUNS}/${id}`

  // THE CONTRACT IS CARRIED, NOT REFERENCED.
  //
  // It used to be a path on the machine, which is why it was never once used:
  // nothing here puts a file on a machine, so the flag named something that
  // could not be made to exist. Now the text comes from this host and is written
  // into the run's own directory.
  //
  // Which is the better arrangement anyway. Rules that govern a run belong beside
  // that run, not in a file somewhere else that can be edited afterwards -- read
  // six weeks later, a path proves nothing about what the worker was actually
  // told, and the whole point of keeping a run record is that it cannot drift.
  const rules = contract ? `${dir}/contract.md` : null

  return `set -u
mkdir -p ${dir}
cd ${q(folder)} 2>/dev/null || cd "$HOME"

# The task as written, byte for byte, so what was asked can be read back later
# rather than reconstructed from a command line.
${heredoc(`${dir}/task.txt`, task, 'OKC_TASK_EOF')}
${rules ? `\n# The rules this run was given, kept with it.\n${heredoc(rules, contract, 'OKC_CONTRACT_EOF')}\n` : ''}
if ! command -v claude >/dev/null 2>&1; then
  echo "okc: claude is not installed on this machine, so it cannot be given work"
  exit 1
fi

# --dangerously-skip-permissions is the point rather than a shortcut. A worker
# that stops to ask cannot run unattended, and asking is exactly what nobody is
# there for. It is defensible HERE and would not be anywhere else: this machine
# cannot reach the dashboard's actions at all, may push one branch and no other,
# cannot touch a default branch, cannot rewrite or delete what it has pushed, and
# is thrown away when the work is done.
#
# WRITTEN TO A FILE AND RUN, rather than passed to "bash -c".
#
# It was bash -c once, and every dispatch it produced died instantly without
# leaving so much as an empty out.log. A shell-quoted path is wrapped in single
# quotes, and putting one inside a single-quoted -c argument ENDS that argument
# -- so the command bash actually received was "cd", with the rest arriving as
# positional parameters. A folder without spaces reassembled by accident and
# hid it; the first folder with a space in it did not.
#
# A file has no such layer: it is written once, verbatim, by a heredoc whose
# delimiter is quoted so nothing here expands. It is also the honest record of
# what ran, sitting beside the task and the output.
cat > ${dir}/run.sh <<'OKC_RUN_EOF'
# Its own pid, first, so a run that dies can be told from one still going. Without
# it a run that was killed reads as "running" forever, because the status file it
# would have written is exactly what never got written.
echo $$ > ${dir}/pid
cd ${q(folder)} 2>/dev/null || cd "$HOME"
claude -p "$(cat ${dir}/task.txt)" --dangerously-skip-permissions --output-format json${rules ? ` --append-system-prompt-file ${rules}` : ''}${resume ? ` --resume ${q(resume)}` : ''} > ${dir}/out.log 2>&1
echo $? > ${dir}/status
OKC_RUN_EOF

# Detached with nohup and its own session, so the run outlives the connection
# that started it -- the channel is how it was asked, not what holds it up.
nohup setsid bash ${dir}/run.sh > /dev/null 2>&1 &

# Recorded immediately, so a run that dies in its first second is still a run
# that happened rather than a directory nobody can account for.
date -u +%Y-%m-%dT%H:%M:%SZ > ${dir}/started
echo okc-dispatched ${id}`
}

// Every run on the machine, newest first, with what became of it.
//
// `status` is written only when the run ends, so its absence is the answer to
// "is it still going" -- and it is reported as a state rather than as a missing
// field, because a caller that has to interpret an absence will eventually
// interpret it as finished.
//
// THREE STATES, NOT TWO. A missing status used to mean running, full stop, which
// is only true while something is still there to write one. A run that was killed
// -- or that never started, which is how the quoting bug above presented -- has no
// status and no process, and reporting that as "running" is a watcher that waits
// forever for a result nobody is going to produce. So the pid is checked: no
// status and nothing alive is `lost`, and says so.
const list = () => `set -u
[ -d ${RUNS} ] || exit 0
for d in ${RUNS}/*/; do
  [ -d "$d" ] || continue
  id=$(basename "$d")
  started=$(cat "$d/started" 2>/dev/null || echo unknown)
  if [ -f "$d/status" ]; then
    state=finished
    code=$(cat "$d/status" 2>/dev/null || echo '?')
  elif [ -f "$d/pid" ] && kill -0 "$(cat "$d/pid")" 2>/dev/null; then
    state=running
    code=
  elif [ -f "$d/pid" ]; then
    state=lost
    code=
  else
    # No pid file yet. Either it is a second old, or it predates the pid being
    # recorded at all -- both are indistinguishable from here, so neither is
    # claimed.
    state=running
    code=
  fi
  lines=$(wc -l < "$d/out.log" 2>/dev/null || echo 0)
  first=$(head -c 160 "$d/task.txt" 2>/dev/null | tr '\\n' ' ')
  echo "okc-run|$id|$state|$code|$started|$lines|$first"
done`

// The tail of one run's raw output. The transcript says what the agent did; this
// says what its own process printed, which is where a crash before it ever
// started thinking shows up.
const output = (id, lines = 40) => `tail -n ${Number(lines) || 40} ${RUNS}/${q(id).slice(1, -1)}/out.log 2>/dev/null || echo "okc: no output for that run"`

function runs (out) {
  return String(out || '').split('\n')
    .map(l => l.trim()).filter(l => l.startsWith('okc-run|'))
    .map(l => l.split('|'))
    .map(([, id, state, code, started, lines, task]) => ({
      id,
      state,
      exit: code === '' ? null : Number(code),
      started,
      outputLines: Number(lines) || 0,
      task: (task || '').trim()
    }))
    .sort((a, b) => String(b.started).localeCompare(String(a.started)))
}

// Readable, sortable, and unique enough for one machine's runs. Not a uuid: this
// is a name somebody types back to ask what happened to it.
const newId = () => 'run-' + new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19)

module.exports = { script, list, output, runs, newId, RUNS, path }

'use strict'

// Signing a machine's worker in, from here.
//
// The sign-in is a conversation: the worker prints a URL, a person visits it and
// authorises, and a code comes back. That is two exchanges with one process,
// which a single command cannot do -- so the process is started detached with
// its input coming from a pipe that stays open, and the code is written into
// that pipe afterwards.
//
// Started HERE rather than by somebody opening a terminal in the machine,
// because the whole point is that the host runs this. A person opening the
// machine and typing is the thing every other part of this replaced.

// Where the sign-in keeps its pipe and its output, on the machine.
const DIR = '$HOME/.okc-auth'

const q = s => `'${String(s).replace(/'/g, `'\\''`)}'`

// Start it, and wait just long enough to have something to say.
//
// The wait is here rather than in the caller because the answer to "sign this
// machine in" is the URL -- returning immediately and making somebody ask again
// would be a worse version of the same round trip.
const begin = seconds => `set -u
mkdir -p ${DIR}
# A previous attempt left a pipe and a process; both would take the input meant
# for this one, and the URL that came back would authorise the wrong attempt.
#
# KILLED BY RECORDED PID, never by pattern. pkill -f matches whole command
# lines, and the shell running this script has the entire script in its own argv
# -- including the line that launches the sign-in. So any pattern that matches
# the thing being killed also matches THIS process, and the script kills itself
# before doing anything at all. It produced no output whatsoever, which is the
# least diagnosable failure available: gone before it could say so. Bracketing
# the pattern fixed only the first of the two places the text appears, which is
# why the second attempt failed identically.
#
# A negative pid kills the process group, which is what setsid made it -- killing
# the wrapper alone would leave the worker holding the pipe.
if [ -f ${DIR}/pid ]; then kill -- -"$(cat ${DIR}/pid)" 2>/dev/null || true; fi
rm -f ${DIR}/in ${DIR}/log ${DIR}/status
mkfifo ${DIR}/in

# Held open by a writer that never writes. Without one the pipe reaches
# end-of-file the moment it is opened, and the worker exits deciding nobody is
# there to answer -- which looks exactly like a sign-in that failed for its own
# reasons.
setsid bash -c 'exec 3> ${DIR}/in; while [ -p ${DIR}/in ]; do sleep 1; done' > /dev/null 2>&1 &

# UNDER A PSEUDO-TERMINAL, because the sign-in is an interactive screen rather
# than a program that prints and reads. Without one it has nowhere to draw and
# says nothing at all -- which is not a failure with a reason, it is silence, and
# silence is the hardest thing to act on.
#
# \`script\` is util-linux and is already on any machine that has a shell. -q so
# its own chatter stays out of the log, -e so the worker's exit status is the one
# recorded rather than script's.
setsid bash -c 'script -qec "claude auth login" /dev/null < ${DIR}/in > ${DIR}/log 2>&1; echo $? > ${DIR}/status' > /dev/null 2>&1 &
echo $! > ${DIR}/pid

# Polled rather than slept at, so a fast answer is not paid for with a fixed
# wait, and a slow one is not cut off early.
for i in $(seq 1 ${seconds}); do
  if grep -qE 'https?://' ${DIR}/log 2>/dev/null; then break; fi
  if [ -f ${DIR}/status ]; then break; fi
  sleep 1
done

echo OKC_AUTH_LOG_BEGIN
cat ${DIR}/log 2>/dev/null
echo OKC_AUTH_LOG_END
[ -f ${DIR}/status ] && echo "OKC_AUTH_EXIT $(cat ${DIR}/status)"

# Said when there is nothing else to say. An empty log is the least actionable
# answer available -- it does not distinguish "still starting" from "the program
# is missing" from "it wrote to a terminal we are not holding" -- so the things
# that tell those apart are reported alongside it.
echo OKC_AUTH_WHY_BEGIN
echo "script: $(command -v script || echo MISSING)"
echo "claude: $(command -v claude || echo MISSING)"
echo "pid: $(cat ${DIR}/pid 2>/dev/null || echo none) alive: $(kill -0 "$(cat ${DIR}/pid 2>/dev/null || echo 0)" 2>/dev/null && echo yes || echo no)"
echo "logsize: $(wc -c < ${DIR}/log 2>/dev/null || echo none)"
echo OKC_AUTH_WHY_END
echo OKC_AUTH_DONE`

// The code, into the pipe the worker is reading.
//
// Then the same poll: it either finishes, or it says why not, and either way the
// answer is its own output rather than an assumption about what silence meant.
const code = (value, seconds) => `set -u
[ -p ${DIR}/in ] || { echo "OKC_AUTH_NO_PIPE"; exit 0; }
printf '%s\\n' ${q(value)} > ${DIR}/in
for i in $(seq 1 ${seconds}); do
  [ -f ${DIR}/status ] && break
  sleep 1
done
echo OKC_AUTH_LOG_BEGIN
cat ${DIR}/log 2>/dev/null
echo OKC_AUTH_LOG_END
[ -f ${DIR}/status ] && echo "OKC_AUTH_EXIT $(cat ${DIR}/status)"
echo OKC_AUTH_DONE`

const cancel = () => `if [ -f ${DIR}/pid ]; then kill -- -"$(cat ${DIR}/pid)" 2>/dev/null || true; fi
rm -f ${DIR}/in ${DIR}/log ${DIR}/status ${DIR}/pid
echo OKC_AUTH_CANCELLED`

// What a terminal was sent, turned back into text.
//
// The sign-in runs under a pseudo-terminal, so what comes back is what a
// terminal would have been asked to DRAW: colour codes, cursor moves, and -- the
// one that matters here -- OSC 8 hyperlinks, which carry the address inside an
// escape sequence and then print it AGAIN as the visible text.
//
// Left in, the URL arrives wrapped in escapes and doubled end to end. It looks
// approximately right, which is worse than looking wrong: it cannot be clicked,
// pasted or opened, and the reason is invisible in the middle of a long query
// string.
const plain = s => String(s || '')
  // Hyperlinks first, keeping the visible text and dropping the target, so the
  // address is not left in twice.
  .replace(/\u001b\]8;;[^\u0007\u001b]*(?:\u0007|\u001b\\)/g, '')
  // Any other operating-system command: window titles, notifications.
  .replace(/\u001b\][^\u0007\u001b]*(?:\u0007|\u001b\\)/g, '')
  // Colours, cursor movement, erase.
  .replace(/\u001b\[[0-9;?]*[ -\/]*[@-~]/g, '')
  .replace(/\u001b[()][0-9A-B]/g, '')
  // Whatever is left that a terminal would have acted on rather than shown.
  .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '')

function read (output) {
  const s = plain(output)
  const a = s.indexOf('OKC_AUTH_LOG_BEGIN')
  const b = s.indexOf('OKC_AUTH_LOG_END')
  const log = a >= 0 && b > a ? s.slice(a + 'OKC_AUTH_LOG_BEGIN'.length, b).trim() : ''
  const exit = /OKC_AUTH_EXIT (\d+)/.exec(s)

  // The first http(s) URL it printed. Trailing punctuation is trimmed because a
  // URL at the end of a sentence collects the full stop, and a URL that does not
  // open is worse than none -- it reads as the tool being broken.
  const url = (log.match(/https?:\/\/\S+/) || [null])[0]

  const c = s.indexOf('OKC_AUTH_WHY_BEGIN')
  const d = s.indexOf('OKC_AUTH_WHY_END')
  const why = c >= 0 && d > c ? s.slice(c + 'OKC_AUTH_WHY_BEGIN'.length, d).trim() : ''

  return {
    url: url ? url.replace(/[.,)\]}'"]+$/, '') : null,
    finished: !!exit,
    exit: exit ? Number(exit[1]) : null,
    log,
    why,
    noPipe: /OKC_AUTH_NO_PIPE/.test(s)
  }
}

module.exports = { begin, code, cancel, read, DIR }

'use strict'

// Laying out a machine's workspace: every repository, on one branch, pointed
// back here.
//
// This file builds a shell script and returns it. It runs nothing and knows
// nothing about machines -- the server hands it to whichever machine asked, over
// the channel that machine is already dialled in on. Keeping it a string means
// it can be read, printed and pasted into a terminal to debug, which a sequence
// of remote calls could not be.
//
// THE TOKEN IS NOT PUT IN A REMOTE URL. It would work, and it would then be in
// `git remote -v`, in `.git/config`, and in the text of every error git prints
// about that remote -- which is the sort of place a secret gets copied out of
// into a screenshot. Git's own credential store holds it instead, in one file
// the machine already could have read, and the remotes stay clean enough to
// show anybody.

// Single-quoted for the shell, with the escape for a quote inside one. Every
// value below crosses into a script, and a repository or branch name is not
// something this file gets to assume the shape of.
const q = s => `'${String(s).replace(/'/g, `'\\''`)}'`

// The default. Named for what it is rather than after any project, and
// overridable per machine -- `spec.folder` -- because where work lives is a
// machine's business and not this app's.
const FOLDER = '$HOME/workspace'

function script ({ repos, branch, folder = FOLDER, origin, machine, token, ca, caFile = '/etc/okc/ca.pem' }) {
  const dir = folder || FOLDER

  // A real loop over the names, rather than the same block written out once per
  // repository. The unrolled version used `continue` to skip a repository that
  // failed, which is only meaningful inside a loop -- outside one the shell
  // refuses it, so a single failure derailed the whole script instead of
  // reporting one repository and carrying on.
  const each = `
for repo in ${repos.map(q).join(' ')}; do
  url="$ORIGIN/git/$repo"
  cd "$WS" || { failed=1; continue; }

  if [ -d "$repo/.git" ]; then
    cd "$repo" || { failed=1; continue; }
    # The address can move -- a rebuilt host, a different port -- and a stale
    # remote fails as "could not resolve", which points at the network rather
    # than at the thing that actually changed.
    git remote set-url origin "$url"
    if ! git fetch --quiet origin </dev/null; then
      echo "$repo: could not fetch from the host"; failed=1; continue
    fi
  else
    if ! git clone --quiet "$url" "$repo" </dev/null; then
      echo "$repo: could not clone from the host"; failed=1; continue
    fi
    cd "$repo" || { failed=1; continue; }
  fi

  # Three ways onto the branch, and the order matters.
  #
  # An existing LOCAL branch is checked out as it is and never reset to the
  # host's copy: on a second visit that copy is behind by exactly the commits
  # made here and not yet pushed, so resetting to it would throw away the work
  # that made the name worth reusing. Uncommitted changes make git refuse the
  # switch, which is also correct -- that is somebody's work, and this is a
  # button, not a decision to discard it.
  if git show-ref --verify --quiet "refs/heads/$branch"; then
    if ! git checkout --quiet "$branch" </dev/null; then
      echo "$repo: could not switch to $branch -- there may be uncommitted changes"; failed=1; continue
    fi
  elif git show-ref --verify --quiet "refs/remotes/origin/$branch"; then
    git checkout --quiet -b "$branch" --track "origin/$branch" </dev/null
  else
    git checkout --quiet -b "$branch" </dev/null
  fi

  echo "$repo: on $(git rev-parse --abbrev-ref HEAD) at $(git log -1 --format=%h 2>/dev/null || echo 'nothing yet')"
done`

  return `set -u
failed=0
WS="${dir}"
branch=${q(branch)}
ORIGIN=${q(origin)}
OKC_CA_FILE=${q(caFile)}

# The authority, written from here rather than fetched.
#
# This script arrives over the channel, which the machine already proved itself
# on and which is itself encrypted -- so handing the certificate down that path
# needs no fingerprint check. The install has to fetch and pin it because at that
# point no such path exists yet; here one does, and using it is both simpler and
# stronger.
${ca ? `sudo -n mkdir -p "$(dirname "$OKC_CA_FILE")" 2>/dev/null || mkdir -p "$(dirname "$OKC_CA_FILE")" 2>/dev/null || true
cat <<'OKC_CA_PEM' > /tmp/okc-ca.pem
${String(ca).trim()}
OKC_CA_PEM
sudo -n install -m 0644 /tmp/okc-ca.pem "$OKC_CA_FILE" 2>/dev/null || install -m 0644 /tmp/okc-ca.pem "$OKC_CA_FILE" 2>/dev/null || true
rm -f /tmp/okc-ca.pem` : '# no authority was supplied; whatever is already on this machine is used'}

mkdir -p "$WS"
cd "$WS" || { echo "could not use $WS"; exit 1; }

# Written before anything reaches the network, so the first clone already has
# what it needs and git never stops to ask a question nobody is there to answer.
umask 077
touch "$HOME/.git-credentials"
chmod 600 "$HOME/.git-credentials"
git config --global credential.helper store
# Replaced rather than appended: this line is this host, and a file that
# accumulated one per visit would keep offering credentials for hosts that are
# gone, oldest first.
tmp=$(mktemp)
grep -vF ${q(origin.replace(/^https?:\/\//, ''))} "$HOME/.git-credentials" > "$tmp" 2>/dev/null || true
printf '%s\\n' ${q(`${origin.replace('://', `://${machine}:${token}@`)}`)} >> "$tmp"
mv "$tmp" "$HOME/.git-credentials"
chmod 600 "$HOME/.git-credentials"

# So a commit made here is attributable to the machine that made it, rather
# than to whatever git guesses from the hostname -- and git refuses to commit
# at all until it has these.
# Git verifies the dashboard against the same authority everything else does.
#
# NOT http.sslVerify=false, which is how a self-signed certificate is usually
# made to work and would leave git accepting any certificate at all -- including
# one belonging to whoever is between this machine and the host, which is the
# entire thing being defended against.
git config --global http.sslCAInfo "$OKC_CA_FILE"

git config --global user.name ${q(machine)} 2>/dev/null || true
git config --global user.email ${q(`${machine}@localhost`)} 2>/dev/null || true
git config --global --add safe.directory '*' 2>/dev/null || true
${each}

echo "workspace is $WS on branch $branch"
exit $failed
`
}

module.exports = { script, FOLDER, folderFor: spec => (spec && spec.folder) || FOLDER, q }

